const icons = [HatIcon, BowlIcon, SwordsIcon, TargetIcon, MugIcon];

const IconGraphic: React.FC<IconGraphicProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 10,
  entranceStagger = 5,
  wobbleSpeed = 0.05,
  wobbleAmount = 15,
  iconScale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const iconBaseSize = 200 * s * iconScale;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "row",
        justifyContent: "space-evenly",
        alignItems: "center",
        padding: `0 ${width * 0.05}px`,
      }}
    >
      {icons.map((IconComponent, i) => {
        const startFrame = i * entranceStagger;

        // Fully hidden before startFrame to prevent layout flashes
        const opacity = interpolate(
          frame,
          [startFrame, startFrame + 1],
          [0, 1],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }
        );

        const popScale = spring({
          fps,
          frame: frame - startFrame,
          config: {
            damping: 12,
            stiffness: 100,
          },
        });

        // Continuous subtle float after landing
        const yOffset =
          Math.sin((frame + i * 20) * wobbleSpeed) * wobbleAmount * s;

        return (
          <div
            key={i}
            style={{
              width: iconBaseSize,
              height: iconBaseSize,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              opacity,
              transform: `scale(${popScale}) translateY(${yOffset}px)`,
              transition: "none",
            }}
          >
            <svg
              width="100%"
              height="100%"
              viewBox="-120 -120 240 240"
              style={{ overflow: "visible" }}
            >
              <IconComponent />
            </svg>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default IconGraphic;